import React, { useMemo } from "react";
import {
    Text,
    ViewStyle,
    TextStyle,
    StyleSheet,
    TouchableOpacity,
    TouchableOpacityProps,
} from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { WaveDotsLoader } from "@/components/loaders/wave-dots-loader";

import { useTheme } from "@/theme/ThemeProvider";
import type { ThemeTokens } from "@/theme/tokens";

export interface ActionButtonProps extends Omit<
    TouchableOpacityProps,
    "style"
> {
    title: string;
    icon?: string;
    variant?: "primary" | "secondary";
    iconPosition?: "pre" | "post";
    isLoading?: boolean;
    disabled?: boolean;
    style?: ViewStyle;
    textStyles?: TextStyle;
    className?: never;
    // borderRadius?: number;
}

export const ActionButton = React.forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    ActionButtonProps
>(
    (
        {
            title,
            icon,
            variant = "primary",
            iconPosition = "post",
            isLoading = false,
            disabled = false,
            style,
            textStyle,
            // borderRadius = 30,
            ...props
        },
        ref,
    ) => {
        const theme = useTheme();
        const styles = useMemo(() => createStyles(theme), [theme]);
        const isDisabled = disabled || isLoading;
        const isSecondary = variant === "secondary";

        const iconColor = isDisabled
            ? theme.foregroundDisabled
            : isSecondary
              ? theme.secondaryForeground
              : theme.primaryForeground;

        return (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.8}
                disabled={isDisabled}
                style={[
                    styles.base,
                    // { borderRadius },
                    isSecondary ? styles.secondary : styles.primary,
                    isDisabled && styles.disabled,
                    style,
                ]}
                {...props}
            >
                {isLoading ? (
                    <WaveDotsLoader />
                ) : (
                    <>
                        {icon && iconPosition === "pre" && (
                            <DynamicIcon
                                name={icon}
                                size={20}
                                color={iconColor}
                            />
                        )}
                        <Text
                            style={[
                                styles.textBase,
                                isSecondary && styles.textSecondary,
                                isDisabled && styles.textDisabled,
                                textStyle,
                            ]}
                        >
                            {title}
                        </Text>
                        {icon && iconPosition === "post" && (
                            <DynamicIcon
                                name={icon}
                                size={20}
                                color={iconColor}
                            />
                        )}
                    </>
                )}
            </TouchableOpacity>
        );
    },
);
ActionButton.displayName = "ActionButton";

const createStyles = (theme: ThemeTokens) =>
    StyleSheet.create({
        base: {
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
            width: "100%",
            marginBottom: 12,
            borderRadius: 16,
            minHeight: 52,
            borderWidth: 1,
        },
        primary: {
            backgroundColor: theme.primary,
            borderColor: "transparent",
        },
        secondary: {
            backgroundColor: theme.secondary,
            borderColor: theme.secondaryForeground,
        },
        disabled: {
            backgroundColor: theme.surfaceMuted,
            borderColor: "transparent",
            opacity: 0.5,
        },
        textBase: {
            fontSize: 16,
            fontWeight: "700",
            color: theme.primaryForeground,
        },
        textSecondary: {
            color: theme.secondaryForeground,
        },
        textDisabled: {
            color: theme.foregroundDisabled,
        },
    });

import React from "react";
import * as LucideIcons from "lucide-react-native";
import { StyleProp, ViewStyle } from "react-native";

export interface DynamicIconProps {
    name: string;
    color?: string;
    size?: number;
    style?: StyleProp<ViewStyle>;
    onPress?: () => void;
}

export function DynamicIcon({
    name,
    color = "#9ca3af",
    size = 20,
    style,
    onPress,
}: DynamicIconProps) {
    const IconComponent = LucideIcons[name as keyof typeof LucideIcons] as any;

    if (!IconComponent) {
        console.warn(`Icon "${name}" does not exist in lucide-react-native.`);
        return null;
    }

    return (
        <IconComponent
            color={color}
            size={size}
            style={style}
            onPress={onPress}
        />
    );
}

// theme/tokens.ts
//
// This is the ONLY place default color values live. The NativeWind engine
// reads this to generate global.css, the Stylesheet engine reads it directly
// as the default theme object. Never hardcode a color anywhere else.

export const defaultThemeValues = {
    background: "#f9fafb",
    surface: "#ffffff",
    surfaceMuted: "#f3f4f6",
    buttonSurface: "#f3f4f6",

    foreground: "#121212",
    foregroundMuted: "#64748b",
    foregroundDisabled: "#9ca3af",

    border: "#e5e7eb",
    borderSubtle: "#f3f4f6",

    primary: "#5f84e0",
    primaryLighter: "#5f84e01a",
    primaryForeground: "#ffffff",

    secondary: "transparent",
    secondaryForeground: "#111827",

    success: "#10b981",
    successBackground: "#10b9811a",
    destructive: "#ef4444",
    destructiveBackground: "#ef44441a",
} as const;

export type ThemeTokens = typeof defaultThemeValues;
export type ThemeTokenKey = keyof ThemeTokens;

import React, { createContext, useContext, useMemo } from "react";
import { defaultThemeValues, type ThemeTokens } from "../../../../theme/tokens"; // Points to your single source of truth

// Create the Context with the default tokens
const ThemeContext = createContext<ThemeTokens>(defaultThemeValues);

export interface ThemeProviderProps {
    /** Only override the tokens you want to change — everything else falls back to defaults */
    theme?: Partial<ThemeTokens>;
    children: React.ReactNode;
}

/**
 * Optional. If the consumer never wraps their app in this, every component
 * still renders using defaultThemeValues — theming is opt-in, not required.
 */
export function ThemeProvider({ theme, children }: ThemeProviderProps) {
    const value = useMemo(() => ({ ...defaultThemeValues, ...theme }), [theme]);
    return (
        <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
    );
}

export function useTheme(): ThemeTokens {
    return useContext(ThemeContext);
}

import React, { useEffect } from "react";
import { StyleSheet, View } from "react-native";
import Animated, {
    withDelay,
    withRepeat,
    withTiming,
    withSequence,
    useSharedValue,
    useAnimatedStyle,
} from "react-native-reanimated";

const Dot = ({ delay, color }: { delay: number; color: string }) => {
    const translateY = useSharedValue(0);
    const opacity = useSharedValue(0.4);

    useEffect(() => {
        translateY.value = withDelay(
            delay,
            withRepeat(
                withSequence(
                    withTiming(-6, { duration: 300 }),
                    withTiming(0, { duration: 300 }),
                ),
                -1,
                true,
            ),
        );
        opacity.value = withDelay(
            delay,
            withRepeat(
                withSequence(
                    withTiming(1, { duration: 300 }),
                    withTiming(0.4, { duration: 300 }),
                ),
                -1,
                true,
            ),
        );
    }, []);

    const style = useAnimatedStyle(() => ({
        transform: [{ translateY: translateY.value }],
        opacity: opacity.value,
    }));

    return (
        <Animated.View
            style={[
                style,
                {
                    width: 7,
                    height: 7,
                    borderRadius: 6,
                    backgroundColor: color,
                    marginHorizontal: 3,
                },
            ]}
        />
    );
};

export function WaveDotsLoader({ color = "#FFFFFF" }: { color?: string }) {
    return (
        <View style={styles.loaderStyles}>
            <Dot delay={0} color={color} />
            <Dot delay={150} color={color} />
            <Dot delay={300} color={color} />
        </View>
    );
}

const styles = StyleSheet.create({
    loaderStyles: {
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        height: 24,
    },
});
